components.css:
.ds-btn { display:inline-flex; align-items:center; justify-content:center; gap:6px; height:2.25rem; padding:0 0.875rem; border:1px solid transparent; border-radius:var(--radius-md, 8px); font-family:Onest, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; font-size:0.875rem; font-weight:500; white-space:nowrap; cursor:pointer; transition:background-color .15s var(--ease-work, cubic-bezier(0.2,0,0,1)), color .15s, border-color .15s, box-shadow .15s; }
.ds-btn-primary { background:var(--color-brand, #2b4be8); color:var(--color-ink-inverse, #ffffff); box-shadow:0 1px 2px rgba(16,23,36,.06); }
.ds-btn-primary:hover, .ds-btn-primary:active { background:var(--color-brand-press, #1e39c4); }
.ds-btn-primary:focus-visible { outline:2px solid var(--color-brand, #2b4be8); outline-offset:2px; }

.ds-btn { display:inline-flex; align-items:center; justify-content:center; gap:6px; height:2.25rem; padding:0 0.875rem; border:1px solid transparent; border-radius:var(--radius-md, 8px); font-family:Onest, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; font-size:0.875rem; font-weight:500; white-space:nowrap; cursor:pointer; transition:background-color .15s var(--ease-work, cubic-bezier(0.2,0,0,1)), border-color .15s, box-shadow .15s; }
.ds-btn-secondary { background:var(--color-surface, #ffffff); color:var(--color-ink, #101724); border-color:var(--color-line-control, #828b9c); box-shadow:0 1px 2px rgba(16,23,36,.06); }
.ds-btn-secondary:hover, .ds-btn-secondary:active { background:var(--color-sunken, #f1f3f7); }
.ds-btn-secondary:focus-visible { outline:2px solid var(--color-brand, #2b4be8); outline-offset:2px; }

.ds-btn { display:inline-flex; align-items:center; justify-content:center; gap:6px; height:1.75rem; padding:0 0.625rem; border:1px solid transparent; border-radius:var(--radius-md, 8px); font-family:Onest, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; font-size:0.75rem; font-weight:500; cursor:pointer; transition:filter .15s, background-color .15s; }
.ds-btn-destructive { background:var(--color-stop, #c02434); color:var(--color-ink-inverse, #ffffff); box-shadow:0 1px 2px rgba(16,23,36,.06); }
.ds-btn-destructive:hover, .ds-btn-destructive:active { filter:brightness(.9); }
.ds-btn-destructive:focus-visible { outline:2px solid var(--color-brand, #2b4be8); outline-offset:2px; }

.ds-menu-item { display:flex; width:100%; align-items:center; gap:8px; border:0; border-radius:var(--radius-sm, 6px); padding:6px 8px; text-align:left; background:transparent; font-family:Onest, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; font-size:0.875rem; color:var(--color-ink-mid, #3d4757); cursor:pointer; transition:background-color .15s, color .15s; }
.ds-menu-item:hover { background:var(--color-sunken, #f1f3f7); color:var(--color-ink, #101724); }
.ds-menu-item:focus-visible { outline:2px solid var(--color-brand, #2b4be8); outline-offset:2px; }

.ds-field-label { display:block; font-family:Onest, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; font-size:0.875rem; font-weight:500; color:var(--color-ink, #101724); }
.ds-field { display:block; width:100%; margin-top:6px; border:1px solid var(--color-line-control, #828b9c); border-radius:var(--radius-md, 8px); background:var(--color-surface, #ffffff); padding:8px 12px; font-family:Onest, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; font-size:0.875rem; color:var(--color-ink, #101724); box-shadow:0 1px 2px rgba(16,23,36,.06); transition:border-color .15s; }
.ds-field::placeholder { color:var(--color-ink-soft, #5f6a78); opacity:1; }
.ds-field:hover { border-color:var(--color-ink-soft, #5f6a78); }
.ds-field:focus-visible { outline:2px solid var(--color-brand, #2b4be8); outline-offset:2px; }
.ds-field-help { margin-top:4px; font-family:Onest, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; font-size:0.8125rem; line-height:1.375; color:var(--color-ink-soft, #5f6a78); }

.ds-rail-row { display:flex; align-items:center; gap:10px; border-radius:var(--radius-md, 8px); padding:6px 8px; font-family:Onest, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; font-size:0.875rem; color:var(--color-ink-mid, #3d4757); text-decoration:none; transition:background-color .15s, color .15s; }
.ds-rail-row:hover { background:var(--color-sunken, #f1f3f7); color:var(--color-ink, #101724); }
.ds-rail-row-current { background:var(--color-brand-tint, #eef1fe); color:var(--color-brand, #2b4be8); font-weight:500; }
.ds-rail-row:focus-visible { outline:2px solid var(--color-brand, #2b4be8); outline-offset:2px; }

.ds-card { display:flex; flex-direction:column; border:1px solid var(--color-line, #e4e7ec); border-radius:var(--radius-md, 8px); background:var(--color-surface, #ffffff); padding:16px; box-shadow:0 1px 2px rgba(16,23,36,.06); font-family:Onest, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; transition:box-shadow .15s; }
.ds-card:hover { box-shadow:0 8px 24px -6px rgba(16,23,36,.12), 0 2px 6px -2px rgba(16,23,36,.06); }
.ds-card-head { display:flex; align-items:flex-start; gap:12px; }
.ds-avatar-agent { display:inline-flex; align-items:center; justify-content:center; width:40px; height:40px; border-radius:7px; background:var(--color-dept-finance, #0e7c5a); color:var(--color-ink-inverse, #ffffff); font-size:0.75rem; font-weight:600; letter-spacing:.025em; flex-shrink:0; }
.ds-card-name { margin:0; font-size:1.0625rem; font-weight:600; letter-spacing:-0.01em; color:var(--color-ink, #101724); }
.ds-species { font-size:0.6875rem; font-weight:500; color:var(--color-ink-soft, #5f6a78); }
.ds-card-meta { margin:2px 0 0; font-size:0.75rem; color:var(--color-ink-soft, #5f6a78); }
.ds-card-line { margin:12px 0 0; font-size:0.875rem; color:var(--color-ink-mid, #3d4757); }
.ds-card-foot { display:flex; align-items:center; justify-content:space-between; gap:12px; margin-top:16px; padding-top:12px; border-top:1px solid var(--color-line, #e4e7ec); }
.ds-status { display:inline-flex; align-items:baseline; gap:6px; font-size:0.75rem; font-weight:500; color:var(--color-ok, #0e7c5a); }
.ds-dot { display:inline-block; width:8px; height:8px; border-radius:9999px; background:var(--color-ok, #0e7c5a); position:relative; top:1px; }
.ds-btn { display:inline-flex; align-items:center; justify-content:center; height:1.75rem; padding:0 0.625rem; border:1px solid transparent; border-radius:var(--radius-md, 8px); font-family:inherit; font-size:0.75rem; font-weight:500; cursor:pointer; transition:background-color .15s; }
.ds-btn-secondary { background:var(--color-surface, #ffffff); color:var(--color-ink, #101724); border-color:var(--color-line-control, #828b9c); box-shadow:0 1px 2px rgba(16,23,36,.06); }
.ds-btn-secondary:hover { background:var(--color-sunken, #f1f3f7); }

.ds-avatar-person { display:inline-flex; align-items:center; justify-content:center; width:32px; height:32px; border-radius:9999px; background:var(--color-sunken, #f1f3f7); color:var(--color-ink-mid, #3d4757); box-shadow:0 0 0 1px var(--color-line, #e4e7ec); font-family:Onest, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; font-size:0.6875rem; font-weight:600; vertical-align:middle; }
.ds-avatar-agent-sm { display:inline-flex; align-items:center; justify-content:center; width:32px; height:32px; border-radius:6px; background:var(--color-dept-support, #7a2fd6); color:var(--color-ink-inverse, #ffffff); font-family:Onest, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; font-size:0.6875rem; font-weight:600; letter-spacing:.025em; vertical-align:middle; }
.ds-chip { display:inline-flex; align-items:center; border:1px solid; border-radius:var(--radius-sm, 6px); padding:1px 6px; margin:0 12px 0 6px; font-family:Onest, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; font-size:0.6875rem; font-weight:600; letter-spacing:.025em; text-transform:uppercase; vertical-align:middle; }
.ds-chip-agent { border-color:rgba(43,75,232,.25); background:var(--color-brand-tint, #eef1fe); color:var(--color-brand, #2b4be8); }
.ds-chip-person { border-color:var(--color-line, #e4e7ec); background:var(--color-sunken, #f1f3f7); color:var(--color-ink-soft, #5f6a78); }

.ds-hold { border:1px solid rgba(180,83,10,.35); background:rgba(180,83,10,.06); border-radius:var(--radius-md, 8px); padding:12px; font-family:Onest, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }
.ds-hold-head { display:flex; flex-wrap:wrap; align-items:center; gap:8px; margin:0; color:var(--color-waiting, #b4530a); }
.ds-hold-title { font-size:0.875rem; font-weight:600; color:var(--color-ink, #101724); }
.ds-hold-intent { font-size:0.75rem; color:var(--color-ink-soft, #5f6a78); }
.ds-hold-args { display:grid; grid-template-columns:minmax(5rem,auto) minmax(0,1fr); gap:4px 16px; margin:8px 0 0; padding-top:8px; border-top:1px solid var(--color-line, #e4e7ec); font-size:0.75rem; }
.ds-hold-args dt { color:var(--color-ink-soft, #5f6a78); }
.ds-hold-args dd { margin:0; color:var(--color-ink-mid, #3d4757); position:relative; overflow-x:auto; }
.ds-hold-risk { margin:8px 0 0; font-size:0.75rem; color:var(--color-ink-mid, #3d4757); }
.ds-hold-actions { display:flex; flex-wrap:wrap; gap:8px; margin-top:12px; }
.ds-btn { display:inline-flex; align-items:center; justify-content:center; height:1.75rem; padding:0 0.625rem; border:1px solid transparent; border-radius:var(--radius-md, 8px); font-family:inherit; font-size:0.75rem; font-weight:500; cursor:pointer; transition:background-color .15s; }
.ds-btn-primary { background:var(--color-brand, #2b4be8); color:var(--color-ink-inverse, #ffffff); }
.ds-btn-primary:hover { background:var(--color-brand-press, #1e39c4); }
.ds-btn-secondary { background:var(--color-surface, #ffffff); color:var(--color-ink, #101724); border-color:var(--color-line-control, #828b9c); }
.ds-btn-secondary:hover { background:var(--color-sunken, #f1f3f7); }
